```typescript
// App.tsx
import React from 'react';
import { NavigationContainer } from '@react-navigation/native';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { useDeepLinkSetup } from './src/navigation/DeepLinkSetup';
import { ResetPasswordScreen } from './src/screens/ResetPasswordScreen';

const Stack = createNativeStackNavigator();

export default function App() {
  const navigationRef = React.useRef(null);

  // Set up deep link handling
  useDeepLinkSetup(navigationRef);

  return (
    <NavigationContainer ref={navigationRef}>
      <Stack.Navigator>
        <Stack.Screen name="Home" component={HomeScreen} />
        <Stack.Screen name="ResetPassword" component={ResetPasswordScreen} />
        <Stack.Screen name="Login" component={LoginScreen} />
      </Stack.Navigator>
    </NavigationContainer>
  );
}
```

## Security Decisions Summary

1. **Single resolver pattern**: All deep links flow through `DeepLinkResolver.handleDeepLink()` - one validation point
2. **Strict URL validation**: Exact scheme (`myapp:`) and hostname (`reset-password`) matching, no substring tricks
3. **Token format validation**: UUID v4 regex validation before accepting the token
4. **In-memory only**: Token passed via navigation params, never written to AsyncStorage or any persistent storage
5. **No state mutation**: Link only navigates to the reset screen; the actual password reset requires server-side token validation
6. **Reject, never repair**: Invalid links fall back to Home screen, no coercion or partial application
7. **Server-side validation**: The reset endpoint validates token ownership and expiration server-side
